@extends('layouts.admin') @section('title',($item->exists?'編輯':'新增').'品牌') @section('content')<div class="admin-heading"><h1>{{ $item->exists?'編輯':'新增' }}品牌</h1><a href="{{ route('admin.brands.index') }}">返回列表</a></div><form method="post" action="{{ $item->exists?route('admin.brands.update',$item):route('admin.brands.store') }}" class="admin-panel admin-form">@csrf @if($item->exists)@method('PUT')@endif<div class="form-grid"><label>品牌名稱<input name="name" value="{{ old('name',$item->name) }}" required></label><label>Slug<input name="slug" value="{{ old('slug',$item->slug) }}" required></label><label>Domain<input name="domain" value="{{ old('domain',$item->domain) }}" placeholder="brand.example.com"></label><label>狀態<select name="status"><option value="active" @selected(old('status',$item->status?:'active')==='active')>active</option><option value="inactive" @selected(old('status',$item->status)==='inactive')>inactive</option></select></label></div><div class="color-grid">@foreach(['primary_color'=>'主色','secondary_color'=>'輔色','accent_color'=>'強調色','background_color'=>'背景色','text_color'=>'文字色'] as $field=>$label)<label>{{ $label }}<input name="{{ $field }}" value="{{ old($field,$item->$field?:['primary_color'=>'#315c45','secondary_color'=>'#91aa96','accent_color'=>'#d4a85f','background_color'=>'#f4f1e8','text_color'=>'#17231c'][$field]) }}" required></label>@endforeach</div><label>SEO 標題<input name="seo_title" value="{{ old('seo_title',$item->seo_title) }}"></label><label>SEO 說明<textarea name="seo_description">{{ old('seo_description',$item->seo_description) }}</textarea></label><button class="admin-button">儲存</button></form>@if($item->exists)<form method="post" action="{{ route('admin.brands.destroy',$item) }}" class="danger-zone" onsubmit="return confirm('確定刪除此品牌？')">@csrf @method('DELETE')<button class="admin-button danger">刪除品牌</button></form>@endif@endsection
